mapper.select:
select count(*) from crisis_alert_log
where user_id = #{userId}
  and create_time >= DATE_SUB(NOW(), INTERVAL #{minutes} MINUTE)

select l.id, l.user_id, l.level, l.keyword_id, l.scene, l.ref_id, l.action_taken, l.reviewed, l.create_time, u.user_name from crisis_alert_log l left join sys_user u on u.user_id = l.user_id
and l.level = #{level} and l.reviewed = #{reviewed}
order by l.create_time desc
